def is_authorized(user, resource):
    """Return True if `user` may read `resource`."""
    if user["role"] == "admin":
        return True
    owner = resource.get("owner")
    return owner == user["id"] or owner is None

def is_authorized(user, resource):
    """Return True if `user` may read `resource`."""
    if user["role"] == "admin":
        return True
    uid = user["id"]
    owner = resource.get("owner")
    if owner is None:
        return True
    return owner == uid

def is_authorized(user, resource):
    """Return True if `user` may read `resource`."""
    if user["role"] != "admin":
        if resource.get("owner") not in (user["id"], None):
            return False
    return True

def is_authorized(user, resource):
    """Return True if `user` may read `resource`."""
    if user["role"] == "admin":
        return True
    allowed = (user["id"], None)
    return resource.get("owner") in allowed
